package br.com.borges.meumedicamento;
import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.content.ContentValues;import android.graphics.Color;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;import org.json.*;
public class MainActivity extends Activity{
 Db db;LinearLayout root;SimpleDateFormat fmt=new SimpleDateFormat("dd/MM HH:mm",new Locale("pt","BR"));
 public void onCreate(Bundle b){super.onCreate(b);db=new Db(this);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);home();}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.rgb(30,40,55));t.setPadding(12,12,12,12);return t;}
 void init(String title){ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setPadding(16,20,16,20);root.setOrientation(1);root.setBackgroundColor(Color.rgb(247,249,252));scroll.addView(root);setContentView(scroll);root.addView(text(title,24));}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);root.addView(b);b.setOnClickListener(v->r.run());}
 EditText input(String hint,String val){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(true);e.setText(val);root.addView(e);return e;}
 void home(){init("Meu Medicamento");button("+ Novo tratamento",()->newMed());button("+ Adicionar familiar",()->newPerson());button("Exportar histórico (CSV)",()->exportCsv());button("Backup (JSON)",()->backup());root.addView(text("Tratamentos e doses",20));try(Cursor c=db.query("SELECT doses.id,people.name,meds.name,meds.dose,doses.due,doses.status,doses.actual FROM doses JOIN meds ON meds.id=doses.med JOIN people ON people.id=meds.person ORDER BY doses.due DESC LIMIT 250")){String last="";while(c.moveToNext()){long id=c.getLong(0),due=c.getLong(4);int status=c.getInt(5);String day=new SimpleDateFormat("dd/MM/yyyy",new Locale("pt","BR")).format(new Date(due));if(!day.equals(last)){root.addView(text(day,19));last=day;}String title=c.getString(1)+" • "+c.getString(2)+" • "+c.getString(3)+" • "+fmt.format(new Date(due));if(status==1)title+=" ✔ Administrado "+fmt.format(new Date(c.getLong(6)));if(status==2)title+=" ✕ Não administrado";root.addView(text(title,14));if(status==0){LinearLayout row=new LinearLayout(this);root.addView(row);Button yes=new Button(this);yes.setText("Administrado");row.addView(yes);yes.setOnClickListener(v->{db.mark(id,1,System.currentTimeMillis());home();});Button no=new Button(this);no.setText("Não administrado");row.addView(no);no.setOnClickListener(v->{db.mark(id,2,0);home();});}else{button("Corrigir registro",()->{db.mark(id,0,0);home();});}}}}
 void newPerson(){init("Adicionar familiar");EditText n=input("Nome","");button("Salvar",()->{String s=n.getText().toString().trim();if(s.isEmpty())return;ContentValues v=new ContentValues();v.put("name",s);db.add("people",v);home();});button("Voltar",()->home());}
 void newMed(){init("Novo tratamento");ArrayList<Integer> ids=new ArrayList<>();ArrayList<String> names=new ArrayList<>();try(Cursor c=db.query("SELECT id,name FROM people ORDER BY name")){while(c.moveToNext()){ids.add(c.getInt(0));names.add(c.getString(1));}}Spinner people=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names);people.setAdapter(adapter);root.addView(text("Pessoa",16));root.addView(people);EditText med=input("Nome do medicamento","");EditText dose=input("Dose prescrita (ex.: 5 mL)","");EditText days=input("Duração em dias","5");days.setInputType(2);EditText hours=input("Horários diários (ex.: 08:00,20:00)","08:00,20:00");root.addView(text("Os horários são fixos por dia. Confirme-os com a prescrição. Não use para calcular doses.",13));button("Salvar tratamento e criar lembretes",()->{try{if(ids.isEmpty())throw new Exception("Cadastre uma pessoa");String name=med.getText().toString().trim(),d=dose.getText().toString().trim();if(name.isEmpty()||d.isEmpty())throw new Exception("Informe medicamento e dose");int count=Integer.parseInt(days.getText().toString());if(count<1||count>365)throw new Exception("Duração entre 1 e 365 dias");String[] times=hours.getText().toString().split(",");if(times.length<1||times.length>12)throw new Exception("Confira horários");Calendar start=Calendar.getInstance();start.set(Calendar.HOUR_OF_DAY,0);start.set(Calendar.MINUTE,0);start.set(Calendar.SECOND,0);start.set(Calendar.MILLISECOND,0);ArrayList<Long> due=new ArrayList<>();for(int day=0;day<count;day++)for(String time:times){String[] p=time.trim().split(":");if(p.length!=2)throw new Exception("Use HH:mm");int h=Integer.parseInt(p[0]),m=Integer.parseInt(p[1]);if(h>23||h<0||m>59||m<0)throw new Exception("Horário inválido");Calendar cal=(Calendar)start.clone();cal.add(Calendar.DAY_OF_YEAR,day);cal.set(Calendar.HOUR_OF_DAY,h);cal.set(Calendar.MINUTE,m);due.add(cal.getTimeInMillis());}ContentValues v=new ContentValues();v.put("person",ids.get(people.getSelectedItemPosition()));v.put("name",name);v.put("dose",d);v.put("start",start.getTimeInMillis());v.put("days",count);v.put("hours",hours.getText().toString());long mid=db.add("meds",v);for(long when:due){ContentValues dv=new ContentValues();dv.put("med",mid);dv.put("due",when);long id=db.add("doses",dv);ReminderReceiver.schedule(this,(int)id,when,names.get(people.getSelectedItemPosition())+": "+name+" ("+d+")");}home();}catch(Exception ex){Toast.makeText(this,ex.getMessage(),Toast.LENGTH_LONG).show();}});button("Cancelar",()->home());}
 void share(String name,String mime,String data){try{java.io.File f=new java.io.File(getCacheDir(),name);try(java.io.FileOutputStream out=new java.io.FileOutputStream(f)){out.write(data.getBytes(java.nio.charset.StandardCharsets.UTF_8));}android.net.Uri uri=androidx.core.content.FileProvider.getUriForFile(this,getPackageName()+".files",f);Intent i=new Intent(Intent.ACTION_SEND);i.setType(mime);i.putExtra(Intent.EXTRA_STREAM,uri);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Exportar arquivo"));}catch(Exception e){Toast.makeText(this,e.toString(),Toast.LENGTH_LONG).show();}}
 void exportCsv(){StringBuilder b=new StringBuilder("Pessoa;Medicamento;Dose;Previsto;Status;Administrado em\n");try(Cursor c=db.query("SELECT people.name,meds.name,meds.dose,doses.due,doses.status,doses.actual FROM doses JOIN meds ON meds.id=doses.med JOIN people ON people.id=meds.person ORDER BY doses.due")){while(c.moveToNext()){int status=c.getInt(4);b.append(c.getString(0)).append(";").append(c.getString(1)).append(";").append(c.getString(2)).append(";").append(fmt.format(new Date(c.getLong(3)))).append(";").append(status==1?"Administrado":status==2?"Não administrado":"Pendente").append(";").append(status==1?fmt.format(new Date(c.getLong(5))):"").append("\n");}}share("historico.csv","text/csv",b.toString());}
 void backup(){try{JSONObject out=new JSONObject();for(String table:new String[]{"people","meds","doses"}){JSONArray arr=new JSONArray();try(Cursor c=db.query("SELECT * FROM "+table)){while(c.moveToNext()){JSONObject item=new JSONObject();for(int i=0;i<c.getColumnCount();i++){String key=c.getColumnName(i);item.put(key,c.isNull(i)?JSONObject.NULL:c.getString(i));}arr.put(item);}}out.put(table,arr);}share("backup-medicamentos.json","application/json",out.toString(2));}catch(Exception e){Toast.makeText(this,e.toString(),Toast.LENGTH_LONG).show();}}
}
